-- afec2493 | هل تجب الزكاة في حلي المرأة المستعمل للُبس المباح؟
UPDATE qa_questions SET
  answer = 'مسألة خلافية. ظاهرُ مذهب الحنابلة — وهو نصُّ الخِرَقيّ في المغني — أنه «لَيْسَ فِى حَلْىِ المَرْأَةِ زَكَاةٌ إذَا كَانَ مِمَّا تَلْبَسُهُ أو تُعِيرُهُ»، وحكاه ابن قدامة كذلك عن مالكٍ والشافعيّ وأبي عبيدٍ وإسحاق وأبي ثور وجماعةٍ من التابعين، وعلَّله بأنه «مُرْصَدٌ لِاسْتِعمالٍ مُبَاحٍ، فلم تَجِبْ فيه الزكاةُ، كالعَوَامِلِ، وثِيَابِ القُنْيَةِ». والقولُ بالوجوب ليس مذهبَ الحنفية وحدَهم كما يُشتهر: المغني يحكيه روايةً ثانيةً عن أحمد، وعن عمرَ وابنِ مسعودٍ وابنِ عباسٍ وعبدِ الله بن عمرو بن العاص وسعيدِ بن المسيَّب وعطاءٍ ومجاهدٍ والزهريّ والثوريّ «وأصْحابِ الرَّأْىِ» — وهم الحنفية. وللقول الأول قيدان مهمّان في المغني: أنّ الإعفاء خاصٌّ بالمُعَدّ للُّبس أو الإعارة، «فأمَّا المُعَدُّ للكِرَا أو النَّفَقَةِ إذا احْتِيجَ إليه، ففيه» «الزكاةُ»؛ وأنّ «ما اتُّخِذَ حِلْيَةً فِرَارًا من الزكاةِ لا يَسْقُطُ عنه». ولا أثر للقلّة والكثرة على ظاهر المذهب: «وقَلِيلُ الحَلْىِ كثِيرُه سَوَاءٌ في الإِباحةِ والزكاةِ».',
  reference = 'المغني لابن قدامة، ت التركي والحلو: ج٤/ص٢٢٠–٢٢٢ (كتاب الزكاة، مسألة: وليس في حلي المرأة زكاة) | الكلمات المفتاحية: زكاة الحلي',
  evidence = 'المغني ج٤/ص٢٢٠ في نصّ الخِرَقيّ وشرحه: «مسألة؛ قال: ولَيْسَ فِى حَلْىِ المَرْأَةِ زَكَاةٌ إذَا كَانَ مِمَّا تَلْبَسُهُ أو تُعِيرُهُ. هذا ظَاهِرُ المَذْهَبِ»، ومَن قال به: «وبه قال القاسمُ، والشَّعْبِيُّ، وقَتادَةُ، ومحمدُ بن عليٍّ، وعَمْرَةُ، ومَالِكٌ، والشَّافِعِيُّ، وأبو عُبَيْدٍ، وإسحاقُ، وأبو ثَوْرٍ». ⚠️ والقولُ بالوجوب ليس قولَ الحنفية وحدَهم: «وذَكَرَ ابنُ أبي موسى عن أحمدَ رِوَايَةً أُخْرَى، أنَّ فيه الزكاةَ»، «ورُوِى ذلك عن عمرَ، وابنِ مسعودٍ، وابنِ عَبَّاسٍ، وعبدِ اللهِ بن عَمْرِو بن العَاصِ، وسَعِيدِ بن المُسَيَّبِ، وسَعِيدِ بن جُبَيْرٍ، وعَطاءٍ، ومُجاهِدٍ، وعبدِ اللَّه بن شَدَّادٍ، وجابِرِ بن زَيْدٍ، وابْنِ سِيرِينَ، ومَيْمُونِ بن مِهْرَانَ، والزُّهْرِيِّ، والثَّوْرِيِّ، وأصْحابِ الرَّأْىِ». وتعليلُ السقوط ج٤/ص٢٢١: «ولأنَّه مُرْصَدٌ لِاسْتِعمالٍ مُبَاحٍ، فلم تَجِبْ فيه الزكاةُ، كالعَوَامِلِ، وثِيَابِ القُنْيَةِ». والقيدُ المهمّ في آخر ج٤/ص٢٢١: «فأمَّا المُعَدُّ للكِرَا أو النَّفَقَةِ إذا احْتِيجَ إليه، ففيه»، وتمامُه في أوّل ج٤/ص٢٢٢: «الزكاةُ؛ لأنَّها إنَّما تَسْقُطُ عمَّا أُعِدَّ للاسْتِعْمَالِ، لِصَرْفِه عن جِهَةِ النَّمَاءِ»، ومثلُه: «وكذلك ما اتُّخِذَ حِلْيَةً فِرَارًا من الزكاةِ لا يَسْقُطُ عنه»، ولا فرق بين قليله وكثيره: «وقَلِيلُ الحَلْىِ كثِيرُه سَوَاءٌ في الإِباحةِ والزكاةِ».',
  verification_status = 'verified'
WHERE id = 'afec2493-1573-4e5d-a2eb-70d6bc1d2f7b'
  AND reference = 'كتب الفقه المقارن | الكلمات المفتاحية: زكاة الحلي'
  AND evidence = 'مسألة خلافية معروفة بين المذاهب الفقهية.'
  AND answer = 'مسألة خلافية بين الفقهاء: جمهورهم يرون عدم وجوب الزكاة في الحلي المُعَدّ للُبس المباح المعتاد، بينما يرى الحنفية وجوبها فيه كسائر الذهب والفضة إذا بلغ نصابًا.';

-- b897b974 | ما حكم الوضوء من مس المرأة الأجنبية؟
UPDATE qa_questions SET
  answer = 'مسألة خلافية مدارُها على معنى ﴿أَوْ لَامَسْتُمُ النِّسَاءَ﴾ [المائدة: ٦]، وحكى المغني فيها ثلاثة أقوال لا قولين: (١) الشافعيّة: ينقض بكل حال لعموم الآية، وحجّتُهم اللغوية أنّ «حَقِيقَةَ اللّمْسِ مُلَاقَاةُ البَشَرَتَيْنِ»، وهي رواية ثالثة عن أحمد. (٢) المشهور من مذهب أحمد، وهو نصُّ الخِرَقيّ: «أنَّ لَمْسَ النِّسَاءِ لِشَهْوةٍ يَنْقُضُ الوُضُوءَ، ولا يَنْقُضُه لِغَيْرِ شَهْوَةٍ»، وبه قال — كما في المغني — علقمةُ وأبو عبيدة والنخعيّ والحكم وحمّادٌ ومالكٌ والثوريّ وإسحاق والشعبيّ. (٣) لا ينقض بحالٍ، وهو رواية ثانية عن أحمد، ورُوي عن عليٍّ وابن عباسٍ وعطاءٍ وطاوسٍ والحسن ومسروق، «وبه قال أبو حَنِيفَة، إلَّا أنْ يَطَأَهَا دُونَ الفَرْجِ فيَنْتَشِرَ فِيها» — فليس مذهبُ الحنفية أنّ اللمس ينقض بالشهوة، بل أنه لا ينقض أصلًا إلا بما ذُكر. وحجّتُهم أنّ الملامسة في الآية «أرادَ به الجِمَاعَ… ولأَنَّهُ ذَكَرَهُ بلَفْظِ المُفَاعَلَةِ، والمُفَاعلةُ لا تكونُ مِنْ أقَلَّ من اثْنَيْن»، وأنّ النبي ﷺ «كانَ يَمَسُّ زَوْجَتَه في الصَّلَاةِ وتَمَسُّه».',
  reference = 'المغني لابن قدامة، ت التركي والحلو: ج١/ص٢٥٦–٢٥٨ (كتاب الطهارة، مسألة: وملاقاة جسم الرجل للمرأة لشهوة) | الكلمات المفتاحية: نقض الوضوء بلمس المرأة',
  evidence = 'المغني ج١/ص٢٥٦ في نصّ الخِرَقيّ وشرحه: «مسألة؛ قال: ومُلَاقاةُ جِسْمِ الرَّجُلِ للمَرْأةِ لِشَهْوَةٍ. المَشْهُورُ مِنْ مَذْهَبِ أحمدَ، رحمه اللهُ، أنَّ لَمْسَ النِّسَاءِ لِشَهْوةٍ يَنْقُضُ الوُضُوءَ، ولا يَنْقُضُه لِغَيْرِ شَهْوَةٍ»، وهو «قَوْلُ عَلْقَمة، وأبى عُبَيْدَة، والنَّخَعِىِّ، والحَكَم» ثم ج١/ص٢٥٧: «وحَمَّاد، ومالِك، والثَّوْرِىِّ، وإسْحاق، والشَّعْبِىِّ». ⚠️ وأبو حنيفة ليس مع هؤلاء: «وعَنْ أَحْمَدَ، رِوَاية ثانِية، لا يَنْقُضُ اللَّمْسُ بحالٍ. ورُوِىَ ذلك عَنْ عَلِىٍّ، وابنِ عَبَّاس، وعَطَاء، وطَاوُس، والحَسَنِ، ومَسْرُوقٍ، وبه قال أبو حَنِيفَة، إلَّا أنْ يَطَأَهَا دُونَ الفَرْجِ فيَنْتَشِرَ فِيها»، ودليلُهم صرفُ الآية عن ظاهرها، قال في تفسير ﴿أَوْ لَامَسْتُمُ النِّسَاءَ﴾ [المائدة: ٦]: «أرادَ به الجِمَاعَ، بدَلِيلِ أنَّ المَسَّ أُرِيدَ به الجِماعُ فكَذَلِكَ اللَّمْسُ، ولأَنَّهُ ذَكَرَهُ بلَفْظِ المُفَاعَلَةِ، والمُفَاعلةُ لا تكونُ مِنْ أقَلَّ من اثْنَيْن». والثالثة هي مذهب الشافعي: «وعن أحمد، رواية ثالِثَة، أنَّ اللَّمْسَ يَنْقُضُ بكُلِّ حالٍ. وهو مَذْهَبُ الشَّافِعِىِّ، لعُمُومِ قولِه تَعالَى» ﴿أَوْ لَامَسْتُمُ النِّسَاءَ﴾ [المائدة: ٦]، وحجّتُه اللغويّة ج١/ص٢٥٨: «وحَقِيقَةُ اللّمْسِ مُلَاقَاةُ البَشَرَتَيْنِ». وحجّةُ المفرِّقين ج١/ص٢٥٨: «واللَّمْسُ لغيرِ شَهْوةٍ لا يَنْقُضُ، لأنَّ النَّبىَّ -صلى اللَّه عليه وسلم- كانَ يَمَسُّ زَوْجَتَه في الصَّلَاةِ وتَمَسُّه».',
  verification_status = 'verified'
WHERE id = 'b897b974-8876-4016-9383-eb0ce1f636fa'
  AND reference = 'كتب الفقه المقارن | الكلمات المفتاحية: نقض الوضوء بلمس المرأة'
  AND evidence = 'مسألة خلافية معروفة بين المذاهب مبنية على تفسير آية "أو لامستم النساء" [المائدة: ٦].'
  AND answer = 'مسألة خلافية بين الفقهاء: الشافعية يرون أن مجرد اللمس بلا حائل ينقض الوضوء، بينما يرى جمهور الحنفية والمالكية والحنابلة أن اللمس لا ينقض الوضوء إلا إذا صحبته شهوة أو أدى لخروج مذي أو مني.';

-- 202e6dfc | ما حكم البيع بالعربون؟
UPDATE qa_questions SET
  answer = 'العربون في البيع — بحدّ المغني — «هو أن يَشْتَرِىَ السِّلْعَةَ، فيَدْفَعَ إلى البائِعِ دِرْهَمًا أو غيرَه، على أنَّه إن أخَذَ السِّلْعَةَ، احْتَسَبَ به من الثَّمَن، وإن لم يَأْخُذْها، فذلك لِلْبَائِعِ». وحكمُه خلافيّ: أجازه أحمد، قال: «لا بَأْسَ به، وفَعَلَه عمرُ رَضِىَ اللَّه عنه»، وأجازه ابن عمر وابن سيرين؛ ومستندُه عند أحمد أثرُ نافع بن عبد الحارث أنه «اشْتَرَى لِعُمَرَ دَارَ السِّجْنِ من صَفْوان بن أُمَيَّةَ، فإن رَضِىَ عمرُ، وإلَّا فلَهُ كذا وكذا»، مع تضعيفه حديثَ النهي. ومنعه مالكٌ والشافعيّ وأصحابُ الرأي، واختاره أبو الخطّاب من الحنابلة، لحديث النهي عن بيع العربون عند ابن ماجه، «ولأنَّه شَرَطَ لِلْبائِعِ شَيْئًا بغير عِوَضٍ، فلم يَصِحَّ… ولأنَّه بمَنْزِلَةِ الخِيارِ المَجْهُولِ، فإنَّه اشْتَرَطَ أنَّ له رَدَّ المَبِيعِ من غيرِ ذِكْرِ مُدَّةٍ» — وقد أقرّ ابنُ قدامة أنّ «هذا هو القِياسُ»، وإنما صار أحمدُ إلى الجواز للأثر عن عمر.',
  reference = 'المغني لابن قدامة، ت التركي والحلو: ج٦/ص٣٣١ (كتاب البيع، فصل في العربون) | الكلمات المفتاحية: بيع العربون',
  evidence = 'المغني ج٦/ص٣٣١ في حدّه: «فصل: والعُرْبُونُ فى البَيْعِ، هو أن يَشْتَرِىَ السِّلْعَةَ، فيَدْفَعَ إلى البائِعِ دِرْهَمًا أو غيرَه، على أنَّه إن أخَذَ السِّلْعَةَ، احْتَسَبَ به من الثَّمَن، وإن لم يَأْخُذْها، فذلك لِلْبَائِعِ»، وفي القول بجوازه: «قال أحْمَدُ: لا بَأْسَ به، وفَعَلَه عمرُ رَضِىَ اللَّه عنه. وعن ابن عمرَ، أنَّه أجازَه. وقال ابنُ سِيرِينَ: لا بَأْسَ به»، وفي مستنَده: «وإنَّما صارَ أحمدُ فيه إلى ما رُوِىَ فيه عن نافِعِ بن عبدِ الحارِثِ، أَنَّه اشْتَرَى لِعُمَرَ دَارَ السِّجْنِ من صَفْوان بن أُمَيَّةَ، فإن رَضِىَ عمرُ، وإلَّا فلَهُ كذا وكذا». وفي المقابل: «واخْتارَ أبو الخَطَّابِ، أنَّه لا يَصِحُّ. وهو قولُ مالِكٍ، والشَّافِعِيِّ، وأصْحابِ الرَّأْىِ، ويُرْوَى ذلك عن ابنِ عَبَّاسٍ والحسنِ؛ لأنَّ النَّبِيَّ -صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ-، نَهَى عن بَيْعِ العُرْبُونِ. رواه ابنُ ماجَه»، وتعليلُهم: «ولأنَّه شَرَطَ لِلْبائِعِ شَيْئًا بغير عِوَضٍ، فلم يَصِحَّ، كما لو شَرَطَه لأجْنَبِيٍّ، ولأنَّه بمَنْزِلَةِ الخِيارِ المَجْهُولِ، فإنَّه اشْتَرَطَ أنَّ له رَدَّ المَبِيعِ من غيرِ ذِكْرِ مُدَّةٍ»، ونصَّ ابن قدامة على أنّ «هذا هو القِياسُ»، وأنّ أحمد «ضَعَّفَ الحَدِيثَ المَرْوِيَّ».',
  verification_status = 'verified'
WHERE id = '202e6dfc-108d-48bd-b8be-9f5b04a175c0'
  AND reference = 'كتب الفقه المقارن | الكلمات المفتاحية: بيع العربون'
  AND evidence = 'مسألة فقهية خلافية معروفة بين المذاهب.'
  AND answer = 'أجازه بعض الفقهاء (كالحنابلة) وهو أن يدفع المشتري جزءًا من الثمن مقدَّمًا يُخصَم من الثمن إن أتم الشراء، ويكون للبائع إن عدل المشتري، بينما منعه جمهور الفقهاء لما فيه من أكل مال بلا مقابل حقيقي عند العدول.';

-- 7ac91fc0 | ما حكم بيع الدَّين لغير من هو عليه؟
UPDATE qa_questions SET
  answer = 'الأصلُ عند الحنابلة أنّ بيع الدين إنما يصحّ ممّن هو في ذمّته لا من غيره: قال في كشاف القناع «وَيَصِحُّ بَيْعُ دَيْنٍ مُسْتَقِرٍّ مِنْ ثَمَنِ مَبِيعٍ وَقَرْضٍ وَمَهْرٍ بَعْدَ دُخُولِهِ وَأُجْرَةٍ اسْتَوْفَى نَفْعَهَا» «وَأَرْشِ جِنَايَةٍ وَقِيمَةِ مُتْلَفٍ وَنَحْوِهِ… لِمَنْ هُوَ… فِي ذِمَّتِهِ» — فقيَّد الصحّةَ بأمرين: أن يكون الدَّينُ مستقرًّا، وأن يكون البيعُ لمن عليه الدَّين. ومن ثمّ لم يُجِزْ بيعَ المسلَم فيه قبل قبضه ولا هبةَ الدَّين «لِغَيْرِ مَنْ هُوَ فِي ذِمَّتِهِ»، لأنّ الدَّين في ذمّة غير المشتري ليس عينًا معيَّنةً مقدورًا على تسليمها. وأشدُّ من ذلك بيعُ الدَّين بدَينٍ مؤجَّل، فقد حكى المغني فيه الإجماع: «قال ابنُ المُنْذِرِ: أجْمَعَ أهْلُ العِلْمِ على أنَّ بَيْعَ الدَّيْنِ بالدَّيْنِ لا يجوزُ»، وإن كان ابنُ قدامة نبَّه على أنّ الحديث المرفوع في النهي عن «بَيْعِ الكَالِىء بالكَالِىء» لم يصحَّ عند أحمد، فالمعوَّل على الإجماع لا عليه. وأمّا صورُ تداول الديون المعاصرة — بيعُها بخصمٍ لطرفٍ ثالث وتوريقُها — فمسألةٌ معاصرة لا نصَّ فيها في هذين الكتابين، وإنما تخريجٌ على هذه القيود، ومحلُّها فتوى معاصرة مسمّاة.',
  reference = 'كشاف القناع عن متن الإقناع للبهوتي، راجعه هلال مصيلحي (٦ أجزاء): ج٣/ص٣٠٦–٣٠٧ (كتاب البيع، فصل من شروط السلم)، والمغني ج٦/ص١٠٦ | الكلمات المفتاحية: بيع الدَّين',
  evidence = 'كشاف القناع ج٣/ص٣٠٦ في ضابط ما يصحّ بيعه من الديون: «وَيَصِحُّ بَيْعُ دَيْنٍ مُسْتَقِرٍّ مِنْ ثَمَنِ مَبِيعٍ وَقَرْضٍ وَمَهْرٍ بَعْدَ دُخُولِهِ وَأُجْرَةٍ اسْتَوْفَى نَفْعَهَا»، وتمامُه ج٣/ص٣٠٧: «وَأَرْشِ جِنَايَةٍ وَقِيمَةِ مُتْلَفٍ وَنَحْوِهِ… لِمَنْ هُوَ… فِي ذِمَّتِهِ»، ودليلُه عنده خبرُ ابن عمر في أخذ الدراهم عن الدنانير. وقبله ج٣/ص٣٠٦ في المسلَم فيه: «وَلَا هِبَةُ دَيْنِ غَيْرِهِ… لِغَيْرِ مَنْ هُوَ فِي ذِمَّتِهِ؛ لِأَنَّ الْهِبَةَ تَقْتَضِي وُجُودَ مُعَيَّنٍ وَهُوَ مُنْتَفٍ هُنَا». وأمّا بيع الدين بالدين فالمغني ج٦/ص١٠٦: «ولنا، أنَّه بَيْعُ دَيْنٍ بِدَيْنٍ، ولا يجوزُ ذلك بالإِجْماعِ. قال ابنُ المُنْذِرِ: أجْمَعَ أهْلُ العِلْمِ على أنَّ بَيْعَ الدَّيْنِ بالدَّيْنِ لا يجوزُ. وقال أحمدُ: إنَّما هو إجْماعٌ»، مع تنبيهه على ضعف المرفوع فيه: «وقد رَوَى أبو عُبَيْدٍ فى ”الغَرِيبِ“، أنَّ النَّبِىَّ -صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ- نَهَى عن بَيْعِ الكَالِىء بالكَالِىء. وَفسَّرَهُ بالدَّيْنِ بالدَّيْنِ»، ثم: «أنَّ الأَثْرَمَ رَوَى عن أحمدَ، أنَّه سُئِلَ: أيَصِحُّ فى هذا حَدِيثٌ؟ قال: لا». ⚠️ وصورُ تداول الديون المعاصرة (بيعُها بخصمٍ لطرفٍ ثالث وتوريقُها) مسألةٌ معاصرة لا نصَّ فيها في الكتابين، وإنما تخريجٌ على هذه القيود.',
  verification_status = 'verified'
WHERE id = '7ac91fc0-c7e5-4fb5-8d9a-c9a0c0bcd3a3'
  AND reference = 'كتب الفقه المقارن | الكلمات المفتاحية: بيع الدَّين'
  AND evidence = 'مسألة فقهية خلافية مبسوطة في كتب الفقه المقارن.'
  AND answer = 'مسألة فقهية خلافية دقيقة، جمهور الفقهاء على منعها أو تقييدها الشديد لما فيها من الغرر والربا المحتمل، إلا في صور محددة أجازها بعض المعاصرين بضوابط.';

-- 59f81777 | ما حكم الاستماع للموسيقى والغناء في الإسلام؟
UPDATE qa_questions SET
  answer = 'مسألة خلافية عريقة، وأدقُّ ما يُقال فيها ما حرَّره ابنُ قدامة في المغني، وفيه ثلاثة تنبيهات: الأول أنّ الخلاف واقعٌ داخل المذهب الواحد لا بين المذاهب فحسب: «واخْتَلفَ أصْحابُنا فى الغِناءِ؛ فذهبَ أبو بكرٍ الخَلَّالُ، وصاحبُه أبو بكرٍ عبدُ العزيزِ، إلى إباحتِه»، «واخْتارَ القاضى أنَّه مَكْروهٌ غيرُ مُحَرَّمٍ. وهو قولُ الشَّافعىِّ، قال: هو مِن اللَّهْوِ المَكْروهِ»، «وذهبَ آخَرون من أصْحابِنا إلى تَحْريمِه» — فالأقوال ثلاثة: إباحة، وكراهة، وتحريم. والثاني أنّ الغناء المجرَّد غيرُ آلات اللهو: فالدفّ عند ابن قدامة «ضَربٌ مُباحٌ»، لكن «الضَّرْبُ به للرِّجالِ فمَكروهٌ على كلِّ حالٍ»، والمعازف والمزامير منهيٌّ عنها في أخبارٍ نقل ابنُ قدامة نفسُه تضعيفَ أبي داود لأحدها. والثالث فرقٌ يغفل عنه كثيرون: «لأنَّ المُحرَّمَ اسْتماعُها دون سَماعِها، والاسْتِماع غيرُ السَّماعِ… والمُسْتمِعُ هو الذى يَقْصِدُ السَّماعَ» — فمن طرَق سمعَه الصوتُ من غير قصدٍ فليس كالقاصد. ويبقى الإنشادُ الخالي من الآلة مباحًا اتفاقًا: «وسائرُ أنواعِ الإِنْشادِ، ما لم يَخْرُجْ إلى حدِّ الغِناءِ»، والحُداءُ «مُباحٌ، لا بَأْسَ فى فِعْلِه وِاسْتِماعِه»؛ والمقارِنُ المحرَّم — من مجونٍ أو خمرٍ أو محرَّمٍ آخر — يُحرَّم لذاته لا لكونه غناءً.',
  reference = 'المغني لابن قدامة، ت التركي والحلو: ج١٤/ص١٥٨–١٦٢ (كتاب الشهادات، فصل في الغناء وآلات الملاهي) | الكلمات المفتاحية: حكم الموسيقى، مسائل خلافية',
  evidence = 'المغني ج١٤/ص١٦٠ في تحرير محلّ الخلاف داخل المذهب نفسه: «فصل: واخْتَلفَ أصْحابُنا فى الغِناءِ؛ فذهبَ أبو بكرٍ الخَلَّالُ، وصاحبُه أبو بكرٍ عبدُ العزيزِ، إلى إباحتِه. قال أبو بكرٍ عبدُ العزيزِ: والغِناءُ والنَّوحُ معنًى واحدٌ، مُباحٌ ما لم يَكُنْ معه مُنْكَرٌ، ولا فيه طَعْنٌ»، ثم: «وممَّن ذهبَ إلى إباحتِه مِن غيرِ كَراهَةٍ، سعدُ بنُ إبراهيمَ، وكثيرٌ مِن أهلِ المدينةِ، والعَنْبَرىُّ»، ودليلُهم حديثُ الجاريتين: «فقال رسولُ اللَّهِ -صلى اللَّه عليه وسلم-: ”دَعْهُمَا، فَإِنَّهَا أَيَّامُ عِيدٍ“. مُتَّفَقٌ عليه»؛ ثم: «واخْتارَ القاضى أنَّه مَكْروهٌ غيرُ مُحَرَّمٍ. وهو قولُ الشَّافعىِّ، قال: هو مِن اللَّهْوِ المَكْروهِ. وقالَ أحمدُ: الغِناءُ يُنبِتُ النِّفاقَ فى القَلبِ، لا يُعْجِبُنِى. وذهبَ آخَرون من أصْحابِنا إلى تَحْريمِه». وآلاتُ اللهو بابٌ آخر ج١٤/ص١٥٩: «وضَربٌ مُباحٌ؛ وهو الدُّفُّ»، «وأما الضَّرْبُ به للرِّجالِ فمَكروهٌ على كلِّ حالٍ»، والمعازفُ والمزاميرُ منهيٌّ عنها بخبرِ أبي أمامة المذكور ج١٤/ص١٥٨ وبأثر ابن عمر فيه، مع أنّ ابن قدامة نقل عن أبي داود في خبر ابن عمر: «رواه الخَلَّالُ، فى ”جامعِه“ من طريقيْنِ، وروَاه أبو داودَ، فى ”سُنَنِه“، وقال: حديثٌ مُنْكَرٌ». وفرقٌ دقيق قرّره ج١٤/ص١٥٨: «لأنَّ المُحرَّمَ اسْتماعُها دون سَماعِها، والاسْتِماع غيرُ السَّماعِ… والمُسْتمِعُ هو الذى يَقْصِدُ السَّماعَ»، ثم ج١٤/ص١٦٢: «وسائرُ أنواعِ الإِنْشادِ، ما لم يَخْرُجْ إلى حدِّ الغِناءِ»، والحُداءُ «مُباحٌ، لا بَأْسَ فى فِعْلِه وِاسْتِماعِه».',
  verification_status = 'verified'
WHERE id = '59f81777-cb1d-4e6f-b205-2e7dff628219'
  AND reference = 'كتب الفقه المقارن | الكلمات المفتاحية: حكم الموسيقى، مسائل خلافية'
  AND evidence = 'مسألة فقهية خلافية معروفة، مبسوطة في كتب الفقه المقارن.'
  AND answer = 'مسألة خلافية بين الفقهاء: جمهورهم يرون الكراهة أو التحريم استنادًا لبعض النصوص والآثار، بينما يرى بعض المعاصرين إباحة ما خلا من محرَّم مصاحب (كالمجون أو الاختلاط المحرَّم) استنادًا لضعف بعض أدلة التحريم عندهم. مسألة تستحق نقاشًا متخصصًا لا حسمًا مبسَّطًا.';

-- 75770a51 | ما أنواع الوقف من حيث المستفيد منه؟
UPDATE qa_questions SET
  answer = 'يُقسَّم الوقف باعتبار الموقوف عليه قسمين، وهو تقسيمٌ منصوصٌ عليه في كتب الحنابلة وإن اختلفت تسميتُه: الأول ما كان الموقوف عليه فيه «آدَمِيًّا مُعَيَّنًا كَزَيْدٍ أَوْ جَمْعًا مَحْصُورًا كَأَوْلَادِهِ أَوْ أَوْلَادِ زَيْدٍ»، وهو الذي يسمّيه المتأخّرون الوقفَ الأهليَّ أو الذُّرّيَّ. والثاني ما كان الموقوف عليه فيه «غَيْرُ الْمَحْصُورِ كَالْوَقْفِ عَلَى جِهَةٍ لَا تَنْحَصِرُ كَالْفُقَرَاءِ، وَالْمَسَاكِينِ»، أو كان على جهةٍ عامّة كـ«مَسْجِدٍ أَوْ مَدْرَسَةٍ أَوْ رِبَاطٍ أَوْ قَنْطَرَةٍ، وَنَحْوِ ذَلِكَ»، وهو الذي يسمّونه الوقفَ الخيريَّ. وليس التقسيم لفظيًّا فحسب، بل تُبنى عليه أحكام: منها أنّ النظر في الأول لمستحقّه المعيَّن، وفي الثاني «لِلْحَاكِمِ أَوْ مَنْ يَسْتَنِيبُهُ». ويصحّ الجمع بين القسمين في وقفٍ واحد، وهو صريحُ متن الخِرَقيّ الذي شرحه ابن قدامة: «ومَنْ وَقَفَ فِي صِحَّةٍ مِنْ عَقْلِهِ وبَدَنِهِ، عَلى قَوْمٍ وأَوْلَادِهِمْ وعَقِبهمْ ثُمَّ آخِرَه لِلمَسَاكِينِ، فَقَدْ زَالَ مِلْكُه عَنْهُ» — فيبدأ أهليًّا وينتهي خيريًّا. (وتسميتا الأهليّ والخيريّ اصطلاحٌ متأخّر لا يوجد في المغني ولا كشاف القناع، وإن صحّ معناهما.)',
  reference = 'كشاف القناع عن متن الإقناع للبهوتي، راجعه هلال مصيلحي (٦ أجزاء): ج٤/ص٢٦٨ (كتاب الوقف، فصل فيمن له النظر)، والمغني ج٨/ص١٨٦ | الكلمات المفتاحية: أنواع الوقف',
  evidence = 'التقسيمُ بالموقوف عليه منصوصٌ في كشاف القناع ج٤/ص٢٦٨: القسم الأول «آدَمِيًّا مُعَيَّنًا كَزَيْدٍ أَوْ جَمْعًا مَحْصُورًا كَأَوْلَادِهِ أَوْ أَوْلَادِ زَيْدٍ»، والثاني «الْمَوْقُوفُ عَلَيْهِ غَيْرُ الْمَحْصُورِ كَالْوَقْفِ عَلَى جِهَةٍ لَا تَنْحَصِرُ كَالْفُقَرَاءِ، وَالْمَسَاكِينِ»، ومثلُه «مَسْجِدٍ أَوْ مَدْرَسَةٍ أَوْ رِبَاطٍ أَوْ قَنْطَرَةٍ، وَنَحْوِ ذَلِكَ» — وعلى هذا التقسيم بُنيت أحكامٌ عمليّة، فنظرُ الأول لمستحقّه ونظرُ الثاني «لِلْحَاكِمِ أَوْ مَنْ يَسْتَنِيبُهُ». والجمعُ بين القسمين في وقفٍ واحد منصوصٌ عليه في متن الخِرَقيّ بالمغني ج٨/ص١٨٦: «ومَنْ وَقَفَ فِي صِحَّةٍ مِنْ عَقْلِهِ وبَدَنِهِ، عَلى قَوْمٍ وأَوْلَادِهِمْ وعَقِبهمْ ثُمَّ آخِرَه لِلمَسَاكِينِ، فَقَدْ زَالَ مِلْكُه عَنْهُ». ⚠️ وأمّا تسميةُ الأول وقفًا أهليًّا (ذُرِّيًّا) والثاني وقفًا خيريًّا فاصطلاحٌ متأخّر: تحقُّقٌ سالب بأداة `--absent-in` على المغني وكشاف القناع معًا لم يُخرج له أثرًا في أيٍّ منهما، فلا يُنسب إليهما وإن صحّ معناه.',
  verification_status = 'verified'
WHERE id = '75770a51-4e7c-4a96-be19-ad63a0de78f1'
  AND reference = 'كتب فقه الوقف | الكلمات المفتاحية: أنواع الوقف'
  AND evidence = 'تقسيم فقهي معروف في كتب الوقف.'
  AND answer = 'الوقف الخيري العام (كالمساجد والمدارس والمستشفيات) ينتفع به عموم الناس، والوقف الأهلي (الذُّري) يُخصَّص لذرية الواقف أو أشخاص معينين، وقد يجمع الوقف بين الغرضين.';

-- e464c5b5 | ما حكم فسخ عقد الوقف بالتراضي بين الواقف والموقوف عليهم؟
UPDATE qa_questions SET
  answer = 'لا يجوز، ولو تراضى الطرفان؛ فالوقف بعد تمامه عقدٌ لازم. قال في كشاف القناع: «وَالْوَقْفُ عَقْدٌ لَازِمٌ… لَا يَجُوزُ فَسْخُهُ بِإِقَالَةٍ وَلَا غَيْرِهَا؛ لِأَنَّهُ عَقْدٌ يَقْتَضِي التَّأْبِيدَ» — والإقالةُ هي عينُ الفسخ بالتراضي، فنصَّ على منعها بخصوصها. ويلزم «بِمُجَرَّدِ الْقَوْلِ بِدُونِ حُكْمِ حَاكِمٍ»، فلا «يَصِحُّ بَيْعُهُ وَلَا هِبَتُهُ وَلَا الْمُنَاقَلَةُ بِهِ» — أي إبدالُه «وَلَوْ بِخَيْرٍ مِنْهُ» — لقوله ﷺ في وقف عمر كما في المغني: «لَا يُبَاعُ أصْلُهَا، ولا يُبْتَاعُ، ولَا يُوهَبُ، ولَا يُورَثُ». ولهذا الأصلِ استثناءٌ واحد عند الحنابلة: أن «تَتَعَطَّلَ مَنَافِعُهُ… الْمَقْصُودَةُ مِنْهُ بِخَرَابٍ… وَتَتَعَذَّرَ عِمَارَتُهُ، وَعَوْدُ نَفْعِهِ»، فيُباع ويُصرف ثمنه في مثله — وهذا استبقاءٌ للوقف بمعناه لا فسخٌ له. على أنّ اللزوم ليس محلَّ اتفاقٍ تامّ كما يُظنّ: نقل المغني عن أبي حنيفة أنّ «الوَقْفَ لا يَلْزَمُ بمُجَرَّدِه، ولِلْوَاقِفِ الرُّجُوعُ فيه، إلَّا أن يُوصِىَ به بعدَ مَوْتِه، فيَلْزَمُ، أو يَحْكُمَ بِلُزُومِه حاكِمٌ»، وأنّ صاحبيه خالفاه إلى قول الجمهور. كما أنّ خروجَ العين عن ملك الواقف هو «الصَّحِيحُ من المَذْهَبِ» ومذهبُ الشافعيّ وأبي حنيفة، «وعن أحمدَ: لا يَزُولُ مِلْكُه. وهو قولُ مالِكٍ» — والخلافُ في الملك لا يقدح في اللزوم.',
  reference = 'كشاف القناع عن متن الإقناع للبهوتي، راجعه هلال مصيلحي (٦ أجزاء): ج٤/ص٢٩٢ (كتاب الوقف، فصل الوقف عقد لازم)، والمغني ج٨/ص١٨٥–١٨٦ | الكلمات المفتاحية: لزوم الوقف بعد تمامه',
  evidence = 'كشاف القناع ج٤/ص٢٩٢ بالنصّ على محلّ السؤال: «فَصْلٌ وَالْوَقْفُ عَقْدٌ لَازِمٌ… لَا يَجُوزُ فَسْخُهُ بِإِقَالَةٍ وَلَا غَيْرِهَا؛ لِأَنَّهُ عَقْدٌ يَقْتَضِي التَّأْبِيدَ، فَكَانَ مِنْ شَأْنِهِ ذَلِكَ»، «وَيَلْزَمُ الْوَقْفُ بِمُجَرَّدِ الْقَوْلِ بِدُونِ حُكْمِ حَاكِمٍ»، «وَلَا يَصِحُّ بَيْعُهُ وَلَا هِبَتُهُ وَلَا الْمُنَاقَلَةُ بِهِ… وَلَوْ بِخَيْرٍ مِنْهُ»، ودليلُه: «لِقَوْلِهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - ”لَا يُبَاعُ أَصْلُهَا وَلَا تُوهَبُ وَلَا تُورَثُ“»؛ واستثناؤه الوحيد: «إلَّا أَنْ تَتَعَطَّلَ مَنَافِعُهُ… الْمَقْصُودَةُ مِنْهُ بِخَرَابٍ… وَتَتَعَذَّرَ عِمَارَتُهُ، وَعَوْدُ نَفْعِهِ» فيُباع ويُصرف ثمنه في مثله. ونصُّ الحديث في المغني ج٨/ص١٨٥: «فإنَّ النبيَّ -صلى اللَّه عليه وسلم- قال لِعُمَرَ في وَقْفِه: ”لَا يُبَاعُ أصْلُهَا، ولا يُبْتَاعُ، ولَا يُوهَبُ، ولَا يُورَثُ“». ⚠️ وليس اللزوم محلَّ اتفاقٍ تامّ: المغني ج٨/ص١٨٥: «وذَهَبَ أبو حنيفةَ إلى أنَّ الوَقْفَ لا يَلْزَمُ بمُجَرَّدِه، ولِلْوَاقِفِ الرُّجُوعُ فيه، إلَّا أن يُوصِىَ به بعدَ مَوْتِه، فيَلْزَمُ، أو يَحْكُمَ بِلُزُومِه حاكِمٌ… وخَالَفَه صَاحِبَاه، فقالا كقَوْلِ سائِر أهْلِ العِلمِ». وكذلك زوالُ الملك ج٨/ص١٨٦: «أنَّ الوَقْفَ إذا صَحَّ، زالَ به مِلْكُ الواقِفِ عنه، في الصَّحِيحِ من المَذْهَبِ. وهو المَشْهُورُ من مذهبِ الشافِعِىِّ، ومذهبِ أبى حَنِيفةَ. وعن أحمدَ: لا يَزُولُ مِلْكُه. وهو قولُ مالِكٍ».',
  verification_status = 'verified'
WHERE id = 'e464c5b5-81af-41b7-80bb-bcd9f06e14b4'
  AND reference = 'كتب فقه الوقف | الكلمات المفتاحية: لزوم الوقف بعد تمامه'
  AND evidence = 'مسألة فقهية مجمَع عليها عند جمهور الفقهاء.'
  AND answer = 'لا يجوز عند جمهور الفقهاء بعد تمام الوقف ولزومه، لأن الوقف يخرج عن ملك الواقف نهائيًا لله تعالى، فلا يملك أحد التراجع عنه ولو بالتراضي.';

-- e86c1a49 | من يتولى إدارة الوقف والإشراف عليه؟
UPDATE qa_questions SET
  answer = 'يتولّاه الناظر (المتولّي)، ومرجعُ تعيينه شرطُ الواقف أوّلًا: «وَيُرْجَعُ إلَى شَرْطِهِ أَيْ: الْوَاقِفِ أَيْضًا فِي النَّاظِرِ فِيهِ». فإن لم يشترط الواقفُ ناظرًا فليس الأمرُ إلى القاضي مطلقًا كما قد يُظنّ، بل يُفصَّل عند الحنابلة: إن كان الموقوف عليه «آدَمِيًّا مُعَيَّنًا كَزَيْدٍ أَوْ جَمْعًا مَحْصُورًا كَأَوْلَادِهِ» فالنظر له هو، «كُلُّ وَاحِدٍ مِنْهُمْ يَنْظُرُ عَلَى حِصَّتِهِ… عَدْلًا كَانَ أَوْ فَاسِقًا؛ لِأَنَّهُ مَلَكَهُ، وَغَلَّتُهُ لَهُ». وأمّا إن كان الوقف على «جِهَةٍ لَا تَنْحَصِرُ كَالْفُقَرَاءِ، وَالْمَسَاكِينِ»، أو على «مَسْجِدٍ أَوْ مَدْرَسَةٍ أَوْ رِبَاطٍ أَوْ قَنْطَرَةٍ»، فنظرُه «لِلْحَاكِمِ أَوْ مَنْ يَسْتَنِيبُهُ» — لأنه «لَيْسَ لَهُ مَالِكٌ مُعَيَّنٌ». وليس للواقف نفسِه بعد لزوم الوقف أن ينصب ناظرًا أو يعزله «لِانْتِفَاءِ مِلْكِهِ». ووظيفة الناظر محدَّدة: «حِفْظُ الْوَقْفِ، وَعِمَارَتُهُ، وَإِيجَارُهُ، وَزَرْعُهُ، وَمُخَاصَمَةٌ فِيهِ، وَتَحْصِيلُ رِيعِهِ… وَالِاجْتِهَادُ فِي تَنْمِيَتِهِ وَصَرْفِهِ فِي جِهَاتِهِ». ويُشترط فيه الإسلام والتكليف و«كِفَايَةٌ فِي التَّصَرُّفِ… وَخِبْرَةٌ بِهِ… وَقُوَّةٌ عَلَيْهِ»، ولا تُشترط «الذُّكُورِيَّةُ؛ لِأَنَّ عُمَرَ أَوْصَى بِالنَّظَرِ إلَى حَفْصَةَ»، ولا «الْعَدَالَةُ» بل «يُضَمُّ إلَى الْفَاسِقِ عَدْلٌ». وله أن يأخذ من الوقف أجرَ عمله: «وَيَأْكُلُ نَاظِرُ الْوَقْفِ الْوَقْفَ بِمَعْرُوفٍ نَصًّا».',
  reference = 'كشاف القناع عن متن الإقناع للبهوتي، راجعه هلال مصيلحي (٦ أجزاء): ج٤/ص٢٦٥ و٢٦٨ و٢٧٠ (كتاب الوقف، فصل يرجع إلى شرط الواقف في الناظر) | الكلمات المفتاحية: ناظر الوقف',
  evidence = 'الأصلُ شرطُ الواقف: كشاف القناع ج٤/ص٢٦٥: «فَصْلٌ وَيُرْجَعُ إلَى شَرْطِهِ أَيْ: الْوَاقِفِ أَيْضًا فِي النَّاظِرِ فِيهِ». ⚠️ فإن لم يشترط ناظرًا فالنظرُ **لا** ينتقل إلى الحاكم مطلقًا، بل ج٤/ص٢٦٨: «وَيَكُونُ النَّظَرُ لِلْمَوْقُوفِ عَلَيْهِ إنْ كَانَ… آدَمِيًّا مُعَيَّنًا كَزَيْدٍ أَوْ جَمْعًا مَحْصُورًا كَأَوْلَادِهِ أَوْ أَوْلَادِ زَيْدٍ… كُلُّ وَاحِدٍ مِنْهُمْ يَنْظُرُ عَلَى حِصَّتِهِ… عَدْلًا كَانَ أَوْ فَاسِقًا؛ لِأَنَّهُ مَلَكَهُ، وَغَلَّتُهُ لَهُ»؛ وإنما يكون للحاكم في غير المحصور والجهات: «الْمَوْقُوفُ عَلَيْهِ غَيْرُ الْمَحْصُورِ كَالْوَقْفِ عَلَى جِهَةٍ لَا تَنْحَصِرُ كَالْفُقَرَاءِ، وَالْمَسَاكِينِ»، «مَسْجِدٍ أَوْ مَدْرَسَةٍ أَوْ رِبَاطٍ أَوْ قَنْطَرَةٍ، وَنَحْوِ ذَلِكَ» فنظرُه «لِلْحَاكِمِ أَوْ مَنْ يَسْتَنِيبُهُ… عَلَى بَلَدِ الْوَقْفِ؛ لِأَنَّهُ لَيْسَ لَهُ مَالِكٌ مُعَيَّنٌ». وليس للواقف نصبُ ناظرٍ بعد لزوم الوقف: «فَلَيْسَ لِلْوَاقِفِ وِلَايَةُ النَّصْبِ… لِانْتِفَاءِ مِلْكِهِ فَلَا يَمْلِكُ النَّصْبَ وَلَا الْعَزْلَ». ووظيفتُه محدَّدة ج٤/ص٢٦٨: «وَوَظِيفَةُ النَّاظِرِ: حِفْظُ الْوَقْفِ، وَعِمَارَتُهُ، وَإِيجَارُهُ، وَزَرْعُهُ، وَمُخَاصَمَةٌ فِيهِ، وَتَحْصِيلُ رِيعِهِ مِنْ أُجْرَةٍ أَوْ زَرْعٍ أَوْ ثَمَرٍ، وَالِاجْتِهَادُ فِي تَنْمِيَتِهِ وَصَرْفِهِ فِي جِهَاتِهِ مِنْ عِمَارَةٍ، وَإِصْلَاحٍ، وَإِعْطَاءٍ مُسْتَحِقٍّ». وشروطُه ج٤/ص٢٧٠: «وَيُشْتَرَطُ فِي النَّاظِرِ الْمَشْرُوطِ إسْلَامٌ»، «تَكْلِيفٌ»، «كِفَايَةٌ فِي التَّصَرُّفِ… وَخِبْرَةٌ بِهِ… وَقُوَّةٌ عَلَيْهِ»، ولا تشترط «الذُّكُورِيَّةُ؛ لِأَنَّ عُمَرَ أَوْصَى بِالنَّظَرِ إلَى حَفْصَةَ»، ولا «الْعَدَالَةُ» بل «يُضَمُّ إلَى الْفَاسِقِ عَدْلٌ». وله أجرُه: «وَيَأْكُلُ نَاظِرُ الْوَقْفِ الْوَقْفَ بِمَعْرُوفٍ نَصًّا».',
  verification_status = 'verified'
WHERE id = 'e86c1a49-33c0-4939-b9ba-f087bf4829f1'
  AND reference = 'كتب فقه الوقف | الكلمات المفتاحية: ناظر الوقف'
  AND evidence = 'مبحث فقهي مبسوط في كتب فقه الوقف.'
  AND answer = 'الناظر (المتولي)، وهو من يحدده الواقف نفسه عند إنشاء الوقف، فإن لم يحدد أحدًا تولت الجهة القضائية أو الرسمية المختصة تعيين ناظر أمين عليه.';

-- b7ad37f3 | هل يجوز وقف المنقولات (كالكتب والأثاث) لا العقار فقط؟
UPDATE qa_questions SET
  answer = 'نعم يصحّ، والضابطُ عند الحنابلة كما في المغني: «أنَّ الذي يجوزُ وَقْفُه، ما جازَ بَيْعُه، وجازَ الانْتِفَاعُ به مع بَقَاءِ عَيْنِه، وكان أصْلًا يَبْقَى بَقَاءً مُتَّصِلًا، كالعَقَارِ، والحَيَواناتِ، والسِّلَاحِ، والأثَاثِ، وأشْباهِ ذلك» — فنصَّ على الأثاث والسلاح والحيوان، لا على العقار وحده، وتدخل الكتبُ تحت الضابط لأنها تُنتفع بها مع بقاء عينها. ودليلُه قوله ﷺ: «أمَّا خَالِدٌ فَقَدِ احْتَبَسَ أدْرَاعَه وَأعْتَادَه فِي سَبِيلِ اللهِ»، والأعتاد كما فسّرها الخطّابيّ «ما يُعِدُّه الرجُلُ من المَرْكُوبِ والسِّلَاحِ وآلةِ الجِهَادِ»، وهي منقولاتٌ كلُّها؛ وتعليلُه أنّ الوقف إنما هو تحبيسُ الأصل وتسبيلُ المنفعة، وذلك حاصلٌ في المنقول: «ولأنَّه يَحْصُلُ فيه تَحْبِيسُ الأصْلِ وتَسْبِيلُ المَنْفَعةِ، فصَحَّ وَقْفُه، كالعَقَارِ». وليست المسألةُ محلَّ إجماع: نقل المغني عن أبي يوسف «لا يجوزُ وَقْفُ الحَيَوانِ، ولا الرَّقِيقِ، ولا الكُرَاعِ، ولا العَرْضِ، ولا السِّلَاحِ»، وعن مالك «في الكُرَاعِ والسِّلَاحِ رِوَايتانِ». وما لا يبقى مع الانتفاع به — كالمطعوم — لا يصحّ وقفه لخروجه عن الضابط.',
  reference = 'المغني لابن قدامة، ت التركي والحلو: ج٨/ص٢٣١–٢٣٢ (كتاب الوقوف، مسألة: ويصح الوقف فيما عدا ذلك) | الكلمات المفتاحية: وقف المنقولات',
  evidence = 'المغني ج٨/ص٢٣١ في نصّ الخِرَقيّ وضابطِ شرحه: «مسألة؛ قال: ويَصِحُّ الْوَقْفُ فِيمَا عَدَا ذلِكَ. وجملةُ ذلك أنَّ الذي يجوزُ وَقْفُه، ما جازَ بَيْعُه، وجازَ الانْتِفَاعُ به مع بَقَاءِ عَيْنِه، وكان أصْلًا يَبْقَى بَقَاءً مُتَّصِلًا، كالعَقَارِ، والحَيَواناتِ، والسِّلَاحِ، والأثَاثِ، وأشْباهِ ذلك». والمخالفُ منصوصٌ ج٨/ص٢٣٢: «وقال أبو يوسفَ: لا يجوزُ وَقْفُ الحَيَوانِ، ولا الرَّقِيقِ، ولا الكُرَاعِ، ولا العَرْضِ، ولا السِّلَاحِ»، «وعن مالِكٍ في الكُرَاعِ والسِّلَاحِ رِوَايتانِ». ودليلُ الجواز ج٨/ص٢٣٢: «ولَنا، أنَّ النبيَّ -صلى اللَّه عليه وسلم- قال: ”أمَّا خَالِدٌ فَقَدِ احْتَبَسَ أدْرَاعَه وَأعْتَادَه فِي سَبِيلِ اللهِ“. مُتَّفَقٌ عليه»، وتفسيرُه: «قال الخَطَّابِىُّ: الأعْتَادُ ما يُعِدُّه الرجُلُ من المَرْكُوبِ والسِّلَاحِ وآلةِ الجِهَادِ»، وتعليلُه: «ولأنَّه يَحْصُلُ فيه تَحْبِيسُ الأصْلِ وتَسْبِيلُ المَنْفَعةِ، فصَحَّ وَقْفُه، كالعَقَارِ». ⚠️ ولم يَرِد لفظُ وقف الكتب في المغني ولا كشاف القناع، وإنما تدخل تحت الضابط المذكور بعمومه.',
  verification_status = 'verified'
