-- 6b324746 | هل يجوز تعزية غير المسلم في وفاة قريبه؟
UPDATE qa_questions SET
  answer = 'المسألة منصوصةٌ في كتب المذهب لا معاصرةٌ محضة. توقَّف الإمام أحمد فيها، وخرَّجها ابنُ قدامة على عيادة أهل الذمّة، وفيها روايتان: «إحْدَاهما، لا نَعُودُهم، فكذلك لا نُعَزِّيهم»، «والثانية، نَعُودُهم» — لعيادته ﷺ الغلامَ اليهوديّ. وعلى الرواية الثانية — وهي التي عليها العمل عند كثيرين — تجوز التعزية بألفاظٍ محدَّدة نقلها المغني بعينها، والفرق بينها دقيق: فإن عزَّيتَ غيرَ المسلم بميّتٍ مسلم قلتَ: «أَحْسَنَ اللهُ عَزَاءَكَ» «وغَفَرَ لِمَيِّتِكَ»؛ وإن عزَّيتَه بميّتٍ غيرِ مسلم — وهو محلّ السؤال — فاللفظُ المنقول: «أَخْلَفَ اللهُ عليك، ولا نَقَصَ عَدَدَكَ»، أو ما اختاره ابنُ بطّة: «أعْطَاكَ اللهُ على مُصِيبَتِكَ أفضلَ ما أعْطَى أحَدًا مِن أهلِ دِينِكَ». والجامعُ في الصيغتين أنّهما دعاءٌ للحيّ بالصبر والخلَف، وليس فيهما دعاءٌ للميّت غير المسلم بمغفرةٍ أو رحمة. وكذلك إن عُزّي المسلمُ بقريبه الكافر، فاللفظ: «أعْظَمَ اللهُ أجْرَكَ، وأحْسَنَ عَزَاءَكَ» — بلا دعاءٍ للميّت.',
  reference = 'المغني لابن قدامة، ت التركي والحلو: ج٣/ص٤٨٦–٤٨٧ (كتاب الجنائز، فصل في التعزية) | الكلمات المفتاحية: تعزية غير المسلم',
  evidence = 'المسألةُ منصوصةٌ لا معاصرةٌ محضة: المغني ج٣/ص٤٨٦: «فصل: وَتَوَقَّفَ أحمدُ، رَحِمَهُ اللهُ، عن تَعْزِيَةِ أهْلِ الذِّمَّةِ، وهى تُخَرَّجُ على عِيادَتِهم، وفيها روَايَتانِ: إحْدَاهما، لا نَعُودُهم، فكذلك لا نُعَزِّيهم؛ لِقَوْلِ النَّبِيِّ -صلى اللَّه عليه وسلم-: ”لا تَبْدَأُوهُمْ بالسَّلَامِ“. وهذا في مَعْنَاه. والثانية، نَعُودُهم» لحديث عيادته ﷺ غلامًا يهوديًّا المرويّ في البخاري كما ذكره. وعلى الرواية الثانية نُقلت ألفاظُ التعزية بعينها: «فعَلَى هذا نُعَزِّيهم فنقولُ في تَعْزِيَتِهم بمُسْلِمٍ: أَحْسَنَ اللهُ عَزَاءَكَ»، وتمامُه أوّلَ ج٣/ص٤٨٧: «وغَفَرَ لِمَيِّتِكَ. وعن كافِرٍ: أَخْلَفَ اللهُ عليك، ولا نَقَصَ عَدَدَكَ»، ونقلَ وجهًا آخر: «وقال أبو عبدِ اللهِ ابن بَطَّةَ، يقولُ: أعْطَاكَ اللهُ على مُصِيبَتِكَ أفضلَ ما أعْطَى أحَدًا مِن أهلِ دِينِكَ». وقبلَه في تعزية المسلم بقريبه الكافر ج٣/ص٤٨٦: «وإن عَزَّى مُسْلِمًا بِكَافِرٍ، قال: أعْظَمَ اللهُ أجْرَكَ، وأحْسَنَ عَزَاءَكَ» — بلا دعاءٍ للميّت.',
  verification_status = 'verified'
WHERE id = '6b324746-9e37-480b-a063-9d877ba5b91e'
  AND reference = 'كتب الفقه المعاصر | الكلمات المفتاحية: تعزية غير المسلم'
  AND evidence = 'مسألة معاصرة مبنية على أصل جواز البر بغير المسلمين المسالمين.'
  AND answer = 'أجاز كثير من الفقهاء المعاصرين تعزية غير المسلم بألفاظ عامة لا تتضمن دعاء له بالمغفرة أو الرحمة الأخروية (كقول "أحسن الله عزاءك" أو "عظّم الله أجرك")، لما في ذلك من بر ومعاملة حسنة مشروعة مع غير المسلمين.';

-- fac8200b | ما حكم طلب العلوم الدنيوية النافعة (كالطب والهندسة) في الإسلام؟
UPDATE qa_questions SET
  answer = 'طلبُها مشروعٌ ومطلوب، وأصلُه في كتب الفقه بابُ فروض الكفايات. وحدُّ فرض الكفاية في كشاف القناع: «مَا قُصِدَ حُصُولُهُ مِنْ غَيْرِ شَخْصٍ مُعَيَّنٍ فَإِنْ لَمْ يُوجَدْ إلَّا وَاحِدٌ تَعَيَّنَ عَلَيْهِ». وقد عدَّ البهوتيّ منه صراحةً «الصَّنَائِعُ الْمُبَاحَةُ الْمُحْتَاجُ إلَيْهَا لِمَصَالِح النَّاسِ غَالِبًا الدِّينِيَّةِ وَالدُّنْيَوِيَّةِ، الْبَدَنِيَّةِ وَالْمَالِيَّةِ، كَالزَّرْعِ وَالْغَرْسِ وَنَحْوِهَا»، وعلَّله بعلّةٍ جامعة: «لِأَنَّ أَمْرَ الْمَعَادِ وَالْمَعَاشِ لَا يَنْتَظِمُ إلَّا بِذَلِكَ» — فما قامت به مصالح الناس من طبٍّ وهندسةٍ وحفرِ آبارٍ وعملِ قناطر وجسورٍ وإصلاح طرقٍ داخلٌ في هذا الأصل. وقيَّده بقيدٍ مهمّ في الأجر لا في الحكم: «فَإِذَا قَامَ بِذَلِكَ أَهْلُهُ بِنِيَّةِ التَّقَرُّبِ كَانَ طَاعَةً وَإِلَّا، فَلَا». ولا تعارُض بينها وبين العلوم الشرعيّة، فقد عدَّ الكشّافُ في فروض الكفايات «الْفَتْوَى وَتَعْلِيمُ الْكِتَابِ وَالسُّنَّةِ، وَسَائِرِ الْعُلُومِ الشَّرْعِيَّةِ» وما يتعلّق بها «مِنْ حِسَابٍ وَنَحْوِهِ، وَلُغَةٍ، وَنَحْوٍ» — فكلاهما فرضُ كفاية في بابه. على أنّ التنصيصَ على الطبّ بعينه محلُّ نظرٍ عند الحنابلة: نقل الكشّاف أنه «فَرْضُ كِفَايَةٍ فِي قَوْلٍ»، وأنّ ابن هبيرة قال به، ثم علَّق: «وَهَذَا غَرِيبٌ فِي الْمَذْهَبِ» — والمعنى أنّ إدراجه في فروض الكفايات مأخوذٌ من عموم قاعدة الصنائع لا من نصٍّ مستقرٍّ فيه بخصوصه.',
  reference = 'كشاف القناع عن متن الإقناع للبهوتي، راجعه هلال مصيلحي (٦ أجزاء): ج٣/ص٣٣–٣٤ (كتاب الجهاد، فصل في فروض الكفايات) | الكلمات المفتاحية: العلوم الدنيوية',
  evidence = 'كشاف القناع ج٣/ص٣٣ في حدّ فرض الكفاية: «وَفَرْضُ الْكِفَايَةِ: مَا قُصِدَ حُصُولُهُ مِنْ غَيْرِ شَخْصٍ مُعَيَّنٍ فَإِنْ لَمْ يُوجَدْ إلَّا وَاحِدٌ تَعَيَّنَ عَلَيْهِ»، ثم عدَّ منه صراحةً: «الصَّنَائِعُ الْمُبَاحَةُ الْمُحْتَاجُ إلَيْهَا لِمَصَالِح النَّاسِ غَالِبًا الدِّينِيَّةِ وَالدُّنْيَوِيَّةِ، الْبَدَنِيَّةِ وَالْمَالِيَّةِ، كَالزَّرْعِ وَالْغَرْسِ وَنَحْوِهَا؛ لِأَنَّ أَمْرَ الْمَعَادِ وَالْمَعَاشِ لَا يَنْتَظِمُ إلَّا بِذَلِكَ»، وقيَّده بالنيّة: «فَإِذَا قَامَ بِذَلِكَ أَهْلُهُ بِنِيَّةِ التَّقَرُّبِ كَانَ طَاعَةً وَإِلَّا، فَلَا». وعدَّ منه كذلك «دَفْعُ ضَرَرِ الْمُسْلِمِينَ، كَسَتْرِ الْعَارِي، وَإِشْبَاعِ الْجَائِعِ»، و«حَفْرُ الْآبَارِ» و«عَمَلُ الْقَنَاطِرِ وَالْجُسُورِ» و«إصْلَاحُ الطُّرُقِ وَالْمَسَاجِدِ؛ لِعُمُومِ حَاجَةِ النَّاسِ إلَى ذَلِكَ»، ومنه «الْفَتْوَى وَتَعْلِيمُ الْكِتَابِ وَالسُّنَّةِ، وَسَائِرِ الْعُلُومِ الشَّرْعِيَّةِ» «وَمَا يَتَعَلَّقُ بِهَا مِنْ حِسَابٍ وَنَحْوِهِ، وَلُغَةٍ، وَنَحْوٍ، وَتَصْرِيفٍ، وَقِرَاءَاتٍ». ⚠️ وأمّا الطبّ بخصوصه ج٣/ص٣٤ فنَقلَ فيه قولًا لا نصًّا مستقرًّا: «إلَّا الطِّبَّ، فَإِنَّهُ فَرْضُ كِفَايَةٍ فِي قَوْلٍ»، ثم: «قَالَ فِي الْآدَابِ الْكُبْرَى: ذَكَرَ ابْنُ هُبَيْرَةَ أَنَّ عِلْمَ الطِّبِّ فَرْضُ كِفَايَةٍ وَهَذَا غَرِيبٌ فِي الْمَذْهَبِ».',
  verification_status = 'verified'
WHERE id = 'fac8200b-827a-4221-888f-11ea84232b55'
  AND reference = 'كتب الفقه المعاصر | الكلمات المفتاحية: العلوم الدنيوية'
  AND evidence = 'أثنى القرآن على التفكر في خلق الكون كباب من أبواب العلم النافع.'
  AND answer = 'مطلوب ومحمود إذا قُصد به نفع الأمة والقيام بفرض الكفاية الذي يحتاجه المجتمع، وليس هناك تعارض بين طلب العلم الشرعي والعلوم الدنيوية النافعة.';
